// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ACCURAL_DEPOSIT} from "../src/ACCURAL_DEPOSIT.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ACCURAL_DEPOSIT c;

    function setUp() public {
        c = new ACCURAL_DEPOSIT();
    }

    function _run(uint256 minSumVal) internal {
        try c.Initialized() {} catch { return; }
        uint256 minSumBefore;
        try c.MinSum() returns (uint256 __r) { minSumBefore = __r; } catch { return; }
        bool reverted;
        try c.SetLogFile(address(0x1234)) { reverted = false; } catch { reverted = true; }
        assertTrue(reverted && c.MinSum() == minSumVal ? c.MinSum() == minSumBefore : true);
    }

    function testFuzz_run(uint256 minSumVal) public {
        _run(minSumVal);
    }

    receive() external payable {}
}
